-- Perbaikan keterbacaan tema gelap: permukaan kartu/pil/input gelap (bukan putih) dan panel menu/chat gelap, agar teks krem/emas terbaca.
update public.live_venues set nm_theme = jsonb_set(jsonb_set(nm_theme, '{ui,white}', '"#143225"'), '{hud}', '{"bg":"rgba(8,28,20,.72)","acc":"#D9A21B","on":"#10241B"}'::jsonb) where key = 'luxury-emerald' and nm_theme #>> '{ui,white}' = '#FFFFFF';
update public.live_venues set nm_theme = jsonb_set(jsonb_set(nm_theme, '{ui,white}', '"#1F1A12"'), '{hud}', '{"bg":"rgba(14,12,9,.72)","acc":"#D9A21B","on":"#1A1408"}'::jsonb) where key = 'luxury-black-gold' and nm_theme #>> '{ui,white}' = '#FFFFFF';

